# AI Office v2.5.1 Hotfix Certification Release Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
Set-Location $Repository
$Stamp=Get-Date -Format "yyyyMMdd-HHmmss"
$Backup=Join-Path $Repository ("workspace\installer-backups\v2.5.1-hotfix-"+$Stamp)
New-Item -ItemType Directory -Path $Backup -Force|Out-Null
function Write-EmbeddedFile{
 param([string]$RelativePath,[string]$Data)
 $Dest=Join-Path $Repository $RelativePath
 New-Item -ItemType Directory -Path (Split-Path -Parent $Dest) -Force|Out-Null
 if(Test-Path $Dest){
   $B=Join-Path $Backup $RelativePath
   New-Item -ItemType Directory -Path (Split-Path -Parent $B) -Force|Out-Null
   Copy-Item $Dest $B -Force
 }
 [IO.File]::WriteAllBytes($Dest,[Convert]::FromBase64String($Data))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\hotfix-manifest.json" -Data ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5.1-Discord-Reliability-Hotfix.md" -Data ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Certify-AIOfficeV251Hotfix.ps1" -Data ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Publish-AIOfficeV251Hotfix.ps1" -Data ""
foreach($Script in @("E:\AI\AI-Office\scripts\intelligence\Certify-AIOfficeV251Hotfix.ps1","E:\AI\AI-Office\scripts\intelligence\Publish-AIOfficeV251Hotfix.ps1")){
 $T=$null;$E=$null;[System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$T,[ref]$E)|Out-Null
 if($E.Count-gt0){throw ("Syntax error in "+$Script+": "+(($E|ForEach-Object{$_.Message})-join"; "))}
}
Write-Host ""
Write-Host "AI Office v2.5.1 hotfix certification/release package installed." -ForegroundColor Green
Write-Host "Production fixes remain unchanged until certification passes." -ForegroundColor Cyan
Write-Host "Backups: $Backup" -ForegroundColor Cyan